import React, { useState } from 'react';
import LoginForm from './components/Auth/LoginForm';
import Sidebar from './components/Layout/Sidebar';
import AdminSidebar from './components/Layout/AdminSidebar';
import TeacherSidebar from './components/Layout/TeacherSidebar';
import ParentSidebar from './components/Layout/ParentSidebar';
import Topbar from './components/Layout/Topbar';
import ContentPanel from './components/Dashboard/ContentPanel';
import AdminContentPanel from './components/Dashboard/AdminContentPanel';
import TeacherContentPanel from './components/Dashboard/TeacherContentPanel';
import ParentContentPanel from './components/Dashboard/ParentContentPanel';
import { users } from './mock/users';

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeItem, setActiveItem] = useState('children-info'); // Valor por defecto
  const [currentUser, setCurrentUser] = useState(null);

  const handleLogin = (credentials) => {
    const user = Object.values(users).find(
      u => u.username === credentials.username && u.password === credentials.password
    );

    if (user) {
      setCurrentUser(user);
      setIsLoggedIn(true);
      // Establecer vista por defecto según el rol
      setActiveItem(user.role === 'Padre de Familia' ? 'children-info' : '');
    } else {
      alert('Credenciales incorrectas');
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    setCurrentUser(null);
    setActiveItem('children-info');
  };

  if (!isLoggedIn) {
    return (
      <div className="min-h-screen bg-gray-100 flex items-center justify-center p-4">
        <LoginForm onLogin={handleLogin} />
      </div>
    );
  }

  const renderSidebar = () => {
    switch(currentUser.role) {
      case 'Director':
        return <Sidebar activeItem={activeItem} setActiveItem={setActiveItem} onLogout={handleLogout} />;
      case 'Administrador':
        return <AdminSidebar activeItem={activeItem} setActiveItem={setActiveItem} onLogout={handleLogout} />;
      case 'Docente':
        return <TeacherSidebar activeItem={activeItem} setActiveItem={setActiveItem} onLogout={handleLogout} />;
      case 'Padre de Familia':
        return <ParentSidebar activeItem={activeItem} setActiveItem={setActiveItem} onLogout={handleLogout} />;
      default:
        return null;
    }
  };

  const renderContentPanel = () => {
    switch(currentUser.role) {
      case 'Administrador':
        return <AdminContentPanel activeItem={activeItem} />;
      case 'Docente':
        return <TeacherContentPanel activeItem={activeItem} />;
      case 'Padre de Familia':
        return <ParentContentPanel activeItem={activeItem} user={currentUser} setActiveItem={setActiveItem} />;
      default:
        return <ContentPanel activeItem={activeItem} userRole={currentUser.role} />;
    }
  };

  return (
    <div className="bg-gray-50 min-h-screen">
      <Topbar user={currentUser} />
      {renderSidebar()}
      {renderContentPanel()}
    </div>
  );
};

export default App;

